page Login "/" {
  state email = ""
  state password = ""
  state loggedIn = false
  state welcomeEmail = ""

  computed valid = email.includes("@") && password.length >= 8

  fn submit() {
    if !valid { return }
    welcomeEmail = email
    loggedIn = true
  }

  column gap=4 pad=4 align=center {
    if loggedIn {
      title `Bienvenido, ${welcomeEmail}`
    } else {
      form gap=3 -> submit() {
        title "Iniciar sesión"
        input email type=email placeholder="Email"
        input password type=password placeholder="Contraseña"
        button "Entrar" primary disabled=(!valid) -> submit()
      }
    }
  }
}

